import{_ as d,o as a,c as r,a as e}from"./chunks/framework.Ld7uezS_.js";const p=JSON.parse('{"title":"9. 法律法规与技术标准","description":"","frontmatter":{},"headers":[],"relativePath":"theory/09-laws-standards.md","filePath":"theory/09-laws-standards.md","lastUpdated":1787283113000}'),l={name:"theory/09-laws-standards.md"};function o(h,t,i,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_9-法律法规与技术标准" tabindex="-1">9. 法律法规与技术标准 <a class="header-anchor" href="#_9-法律法规与技术标准" aria-label="Permalink to &quot;9. 法律法规与技术标准&quot;">​</a></h1><h2 id="本章学习目标" tabindex="-1">本章学习目标 <a class="header-anchor" href="#本章学习目标" aria-label="Permalink to &quot;本章学习目标&quot;">​</a></h2><p>学完本章，你应该能区分法律法规、强制性工程建设规范、推荐性国家标准、单位制度和设备说明书的作用；遇到固定数值或操作要求时，知道应先查哪一类来源。</p><h2 id="一、规范层级怎么理解" tabindex="-1">一、规范层级怎么理解 <a class="header-anchor" href="#一、规范层级怎么理解" aria-label="Permalink to &quot;一、规范层级怎么理解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源层级</th><th>主要回答的问题</th><th>学习时的用法</th></tr></thead><tbody><tr><td>法律、行政法规</td><td>谁负责、必须做什么、违反后承担什么责任</td><td>查消防职责、生产安全和法律责任</td></tr><tr><td>强制性工程建设规范</td><td>建设和使用中必须满足的底线要求</td><td>查 GB 55036、GB 55037 等现行强制要求</td></tr><tr><td>国家标准/行业标准</td><td>设计、施工、验收、维护和检测如何实施</td><td>查具体系统的技术方法和判定条件</td></tr><tr><td>单位制度/操作规程</td><td>本单位具体岗位怎样执行</td><td>决定值班、审批、报告和现场流程</td></tr><tr><td>设备说明书</td><td>某一型号设备按钮、状态和限制</td><td>决定具体设备的操作方式，不被通用口诀替代</td></tr></tbody></table><h2 id="二、必须优先关注的通用规范" tabindex="-1">二、必须优先关注的通用规范 <a class="header-anchor" href="#二、必须优先关注的通用规范" aria-label="Permalink to &quot;二、必须优先关注的通用规范&quot;">​</a></h2><ul><li><strong>GB 55036-2022《消防设施通用规范》</strong>：自 2023-03-01 起实施，属于强制性工程建设规范，全部条文必须严格执行。</li><li><strong>GB 55037-2022《建筑防火通用规范》</strong>：住房和城乡建设部公告 2022 年第 189 号批准，自 2023-06-01 起实施，属于强制性工程建设规范，全部条文必须严格执行。</li></ul><p>现行工程建设标准与上述通用规范不一致时，应以通用规范规定为准。GB 55037 实施公告同时明确废止了 GB 50016-2014（2018 年版）部分强制性条文；因此不能简单说“GB 50016 全部废止”，也不能忽略 GB 55037。具体条文、适用范围和现行状态请在<a href="https://openstd.samr.gov.cn/" target="_blank" rel="noreferrer">国家标准全文公开系统</a>核验。</p><h2 id="三、同一个问题应该查哪类依据" tabindex="-1">三、同一个问题应该查哪类依据 <a class="header-anchor" href="#三、同一个问题应该查哪类依据" aria-label="Permalink to &quot;三、同一个问题应该查哪类依据&quot;">​</a></h2><p>判断依据不能只看文件名称，还要先看问题处于哪个阶段。可以把“查依据”理解成给问题找合适的工具：法律法规回答“谁负责、必须不必须”，工程标准回答“技术上怎么做”，单位制度回答“在本单位由谁审批、谁记录”，设备说明书回答“这一型号具体怎么操作”。同一件事可能需要同时查几类文件，不能只拿一份文件包打天下。</p><table tabindex="0"><thead><tr><th>现场问题</th><th>首先关注</th><th>还要结合</th><th>不能直接替代</th></tr></thead><tbody><tr><td>建筑或系统怎样设计</td><td>强制性工程建设规范、设计文件</td><td>专业标准、审查意见</td><td>不能用设备说明书替代建筑设计要求</td></tr><tr><td>设备怎样安装、调试和验收</td><td>施工验收标准、批准的施工记录</td><td>产品说明书、设计文件</td><td>不能把一次验收结果当作长期运行证明</td></tr><tr><td>日常怎样巡查和维护</td><td>建筑消防设施维护管理要求、单位制度</td><td>设备说明书、历史记录</td><td>不能用“看起来干净”替代功能检查</td></tr><tr><td>故障怎样判断和维修</td><td>故障现象、维修规程、说明书和授权范围</td><td>设计文件、检测结果</td><td>不能先换件再猜原因，也不能短接掩盖故障</td></tr><tr><td>现场报警或火灾怎样处置</td><td>法律法规、应急预案和人员安全要求</td><td>控制器信息、现场核实、通信记录</td><td>不能用教材口诀替代现场指挥和专业救援</td></tr></tbody></table><h3 id="冲突-时的判断顺序" tabindex="-1">“冲突”时的判断顺序 <a class="header-anchor" href="#冲突-时的判断顺序" aria-label="Permalink to &quot;“冲突”时的判断顺序&quot;">​</a></h3><ol><li>先确认文件是否适用于当前建筑、系统、设备型号和工作阶段；</li><li>先满足法律法规和强制性要求，再执行专业标准、设计文件和单位流程；</li><li>对具体按钮、状态灯、接口和恢复方法，以设备说明书及现场批准文件核对；</li><li>发现不同来源表述不一致时，停止猜测，记录差异并向技术负责人或主管部门核实；</li><li>涉及固定数值时，同时记录数值、单位、测点、仪器、环境、版本和判定依据。</li></ol><p>例如，施工验收文件中的某项测试结果，只能说明相应阶段、相应条件下的结果，不能自动证明设备在多年运行后仍然满足要求；日常维护记录也不能替代法定检测报告。</p><h2 id="三、法律案例化学习" tabindex="-1">三、法律案例化学习 <a class="header-anchor" href="#三、法律案例化学习" aria-label="Permalink to &quot;三、法律案例化学习&quot;">​</a></h2><h3 id="《消防法》第十六条-单位职责" tabindex="-1">《消防法》第十六条：单位职责 <a class="header-anchor" href="#《消防法》第十六条-单位职责" aria-label="Permalink to &quot;《消防法》第十六条：单位职责&quot;">​</a></h3><p>单位要建立责任制和制度，配置、维护消防设施，保持疏散和消防车道畅通，开展检查、检测和演练。看到“通道堵塞”“设施长期故障”“没有检测记录”等题干，应从单位主体责任角度判断。</p><h3 id="《消防法》第二十八条-不得占用、堵塞、封闭疏散通道和安全出口" tabindex="-1">《消防法》第二十八条：不得占用、堵塞、封闭疏散通道和安全出口 <a class="header-anchor" href="#《消防法》第二十八条-不得占用、堵塞、封闭疏散通道和安全出口" aria-label="Permalink to &quot;《消防法》第二十八条：不得占用、堵塞、封闭疏散通道和安全出口&quot;">​</a></h3><p>题目出现消防通道堆物、出口锁闭或疏散路径被占用时，重点判断是否影响人员逃生和消防救援，不要把它当作普通物业问题。</p><h3 id="《消防法》第四十四条-报警和组织救援" tabindex="-1">《消防法》第四十四条：报警和组织救援 <a class="header-anchor" href="#《消防法》第四十四条-报警和组织救援" aria-label="Permalink to &quot;《消防法》第四十四条：报警和组织救援&quot;">​</a></h3><p>发现火灾应立即报警；人员应先组织、引导在场人员疏散。具体报警和现场处置还要结合单位预案和人员安全。</p><h3 id="《消防法》第五十一条-火灾现场保护和调查" tabindex="-1">《消防法》第五十一条：火灾现场保护和调查 <a class="header-anchor" href="#《消防法》第五十一条-火灾现场保护和调查" aria-label="Permalink to &quot;《消防法》第五十一条：火灾现场保护和调查&quot;">​</a></h3><p>火灾扑灭后，应按要求保护现场、接受调查，不擅自清理或破坏可能影响原因认定的痕迹物证。</p><blockquote><p><strong>版本提示（访问核查：2026-08-20）</strong>：本站只引用上述条号的教学概述，不复制旧页面的机构称谓或整段法条。全国人大部分旧页面仍可能出现修法前“公安机关消防机构”等表述；学习和考试前应通过<a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">全国人大国家法律法规数据库</a>核对《消防法》现行文本，并结合 2021 年修正后的地方政府正式汇编或主管部门现行文本复核。本站不以旧页面作为现行机构称谓的唯一依据。</p></blockquote><h2 id="四、法规与标准的考试判断方法" tabindex="-1">四、法规与标准的考试判断方法 <a class="header-anchor" href="#四、法规与标准的考试判断方法" aria-label="Permalink to &quot;四、法规与标准的考试判断方法&quot;">​</a></h2><p>遇到“依据什么处理”的题目，按以下顺序判断：</p><ol><li><strong>先看问题属于哪个阶段</strong>：设计、施工安装、调试验收、日常维护、维修更换还是岗位处置；</li><li><strong>再看来源类型</strong>：法律法规解决责任，强制性工程建设规范解决底线，专业标准解决技术方法，设备说明书解决型号操作；</li><li><strong>核对版本和适用对象</strong>：不要把旧版教材、地方公告或某品牌手册外推成全国统一规则；</li><li><strong>最后看现场授权和记录</strong>：涉及停用、断电、联动测试或维修时，要有审批、告知、监护、复测和恢复记录。</li></ol><h3 id="一个-设备说明书与单位规程不一致-的例子" tabindex="-1">一个“设备说明书与单位规程不一致”的例子 <a class="header-anchor" href="#一个-设备说明书与单位规程不一致-的例子" aria-label="Permalink to &quot;一个“设备说明书与单位规程不一致”的例子&quot;">​</a></h3><p>假设设备说明书写的是某型号控制器的菜单操作，单位规程又要求联动测试前必须登记、通知控制室和设置现场监护。两者并不一定冲突：说明书解决“按钮和菜单怎么用”，单位规程解决“本单位在什么条件下允许使用、谁批准、如何告知和记录”。如果单位规程要求的安全条件没有满足，不能因为说明书写了菜单步骤就直接操作。</p><p>再假设旧教材写了一个固定动作时间，而现行检测方案或设备说明书采用了不同的测试条件。此时不能凭记忆选一个数字，应先确认测试对象、测点、单位、系统形式、来源版本和适用阶段；无法确认时保留“待依据核验”，向技术负责人或鉴定站确认。</p><h3 id="几个容易混淆的标准" tabindex="-1">几个容易混淆的标准 <a class="header-anchor" href="#几个容易混淆的标准" aria-label="Permalink to &quot;几个容易混淆的标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标准</th><th>主要用途</th><th>不应混淆的内容</th></tr></thead><tbody><tr><td>GB 50116</td><td>火灾自动报警系统设计</td><td>不能代替施工验收或维护记录要求</td></tr><tr><td>GB 50166</td><td>火灾自动报警系统施工、调试和验收</td><td>不能把验收参数直接当日常巡查阈值</td></tr><tr><td>GB 50974</td><td>消防给水和消火栓系统</td><td>设计、施工、验收、维护条款要按章节和场景看</td></tr><tr><td>GB 51251</td><td>防烟排烟系统设计、施工、调试和维护</td><td>风量、风压和动作条件不能脱离设计文件</td></tr><tr><td>GB 51309</td><td>应急照明和疏散指示系统</td><td>照度、转换和持续时间需结合建筑及系统类型</td></tr><tr><td>GB 25201</td><td>建筑消防设施维护管理</td><td>规定维护管理框架，不替代每种设备的产品说明书</td></tr></tbody></table><h2 id="五、常用标准索引" tabindex="-1">五、常用标准索引 <a class="header-anchor" href="#五、常用标准索引" aria-label="Permalink to &quot;五、常用标准索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>代表性标准</th><th>学习用途</th></tr></thead><tbody><tr><td>火灾自动报警</td><td>GB 50116、GB 50166</td><td>报警系统设计、施工验收和功能关系</td></tr><tr><td>自动喷水灭火</td><td>GB 50084、GB 50261</td><td>喷淋系统类型、组件和验收</td></tr><tr><td>消防给水和消火栓</td><td>GB 50974</td><td>水源、管网、消火栓和泵组</td></tr><tr><td>防烟排烟</td><td>GB 51251</td><td>送风、排烟、风阀和反馈</td></tr><tr><td>应急照明和疏散指示</td><td>GB 51309</td><td>疏散照明、指示和供电</td></tr><tr><td>灭火器</td><td>GB 50140、GB 50444</td><td>配置、检查和维护</td></tr><tr><td>建筑消防设施维护</td><td>GB 25201</td><td>日常维护、记录和故障处理</td></tr><tr><td>爆炸危险环境电力装置</td><td>GB 50058</td><td>防爆区域和设备选型基础</td></tr><tr><td>剩余电流保护</td><td>GB/T 13955</td><td>剩余电流保护装置的选用和安装基础</td></tr></tbody></table><h2 id="五、自测" tabindex="-1">五、自测 <a class="header-anchor" href="#五、自测" aria-label="Permalink to &quot;五、自测&quot;">​</a></h2><ol><li>GB 55036、GB 55037 为什么需要优先核验？</li><li>GB 50016 与 GB 55037 的关系应如何表述才不绝对化？</li><li>设备说明书和国家标准分别解决什么问题？</li><li>发现疏散通道被占用时，涉及哪个主体责任和消防风险？</li></ol><blockquote><p>参考：</p><ul><li><a href="https://www.gov.cn/zhengce/zhengceku/2023-01/30/content_5739161.htm" target="_blank" rel="noreferrer">住房和城乡建设部关于发布《建筑防火通用规范》的公告</a>，住房和城乡建设部公告 2022 年第 189 号，2022-12-27 发布。</li><li><a href="https://openstd.samr.gov.cn/" target="_blank" rel="noreferrer">国家标准全文公开系统</a>。</li><li>《中华人民共和国消防法》现行文本请通过<a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">全国人大国家法律法规数据库</a>检索核对。</li><li>《中华人民共和国安全生产法》现行文本请通过<a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">全国人大国家法律法规数据库</a>检索核对。</li></ul></blockquote>',37)])])}const u=d(l,[["render",o]]);export{p as __pageData,u as default};
